/**
 * scripts/postbuild.ts: runs after `next build` (see package.json "build").
 *
 * 1. Adds a Content-Security-Policy <meta> tag to every HTML page in ./out, listing the
 *    SHA-256 hash of each inline script Next put on that page. No 'unsafe-inline', no nonce.
 * 2. Writes ./out/_headers (Cloudflare format): security headers for every route.
 * 3. Writes ./out/.well-known/security.txt from site.config.ts, stamped to expire in under a year.
 * 4. Copies ./NOTICES (third-party licences, generated by scripts/licences.ts) to ./out/NOTICES.txt.
 *
 * Why the script rules live in a <meta> tag and not the header: Cloudflare limits each
 * _headers line to 2,000 characters, and a page can need ~2,000 characters of hashes.
 * Browsers enforce every CSP they receive, so header + meta together give one strict policy.
 * The header deliberately has no default-src/script-src (it would block the hashed scripts);
 * it carries everything else, including the header-only frame-ancestors. Static assets get
 * an extra `default-src 'none'` policy.
 *
 * Limit to know: the hashes are taken from the built pages, so this protects visitors from
 * injected content, not from a build tool that was itself tampered with. scripts/check-export.ts
 * narrows that by accepting only the exact inline-script forms Next.js emits.
 *
 * If this fails, the build fails: a page can't ship without its CSP.
 * Depends on: site.config.ts, NEXT_PUBLIC_WAITLIST_ENDPOINT (already validated by the Next build).
 */

import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readdirSync, readFileSync, realpathSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

export type HeaderInputs = {
  /** e.g. "https://example.app" or "https://hap008.github.io/atlas-site" */
  siteUrl: string;
  /** "" at a domain root, "/atlas-site" on GitHub Pages */
  basePath: string;
  /** The exact form endpoint this build posts to (origin + path), or null when the waitlist isn't connected. */
  formEndpoint: string | null;
  hsts: { maxAgeSeconds: number; includeSubDomains: boolean };
};

/** Every browser feature the site doesn't use is switched off. It uses none of them. */
export const DENIED_FEATURES = [
  "accelerometer",
  "autoplay",
  "bluetooth",
  "browsing-topics",
  "camera",
  "display-capture",
  "encrypted-media",
  "fullscreen",
  "geolocation",
  "gyroscope",
  "hid",
  "idle-detection",
  "magnetometer",
  "microphone",
  "midi",
  "payment",
  "picture-in-picture",
  "publickey-credentials-get",
  "screen-wake-lock",
  "serial",
  "usb",
  "xr-spatial-tracking",
] as const;

const INLINE_SCRIPT = /<script(?![^>]*\ssrc=)[^>]*>([\s\S]*?)<\/script>/g;

export function inlineScriptHashes(html: string): string[] {
  const hashes = [...html.matchAll(INLINE_SCRIPT)].map(
    (m) => `'sha256-${createHash("sha256").update(m[1], "utf8").digest("base64")}'`,
  );
  return [...new Set(hashes)];
}

/** Reduces a form endpoint to origin + path, the most a CSP source can pin. Null if unset. */
export function formSource(endpoint: string | null | undefined): string | null {
  const value = endpoint?.trim();
  if (!value) return null;
  const url = new URL(value);
  return `${url.origin}${url.pathname}`;
}

function sharedDirectives({ siteUrl, formEndpoint }: HeaderInputs): string[] {
  return [
    "style-src 'self'",
    "img-src 'self'",
    "font-src 'self'",
    // Pinned to this build's own form, not the whole form service. No form connected: nowhere at all.
    formEndpoint ? `connect-src 'self' ${formEndpoint}` : "connect-src 'self'",
    "media-src 'self'",
    "manifest-src 'self'",
    "object-src 'none'",
    "frame-src 'none'",
    "child-src 'none'",
    "worker-src 'none'",
    "base-uri 'self'",
    formEndpoint ? `form-action ${formEndpoint}` : "form-action 'none'",
    // Only meaningful (and only safe for local http testing) on an https site.
    ...(siteUrl.startsWith("https://") ? ["upgrade-insecure-requests"] : []),
  ];
}

/** The per-page policy for the <meta> tag: the script rules plus everything a meta tag can carry. */
export function metaCsp(inputs: HeaderInputs, scriptHashes: string[]): string {
  return [
    "default-src 'self'",
    ["script-src 'self'", ...scriptHashes].join(" "),
    "script-src-attr 'none'",
    ...sharedDirectives(inputs),
  ].join("; ");
}

/** The policy sent as a response header on every route. No default-src/script-src: see the file header. */
export function headerCsp(inputs: HeaderInputs): string {
  return ["script-src-attr 'none'", ...sharedDirectives(inputs), "frame-ancestors 'none'"].join("; ");
}

export function insertMetaCsp(html: string, policy: string): string {
  // The policy goes into an HTML attribute unescaped, so it must not be able to close it.
  if (/["&<>]/.test(policy)) throw new Error("CSP contains a character that is not safe in an HTML attribute");
  if (/http-equiv="Content-Security-Policy"/i.test(html)) {
    throw new Error("page already has a CSP meta tag (postbuild ran twice?)");
  }
  const anchor = /<meta charSet="utf-8"\s*\/>/i;
  if (!anchor.test(html)) throw new Error("could not find <meta charSet> to place the CSP after");
  // Right after the charset: before any script or stylesheet, so the policy governs all of them.
  return html.replace(anchor, (m) => `${m}<meta http-equiv="Content-Security-Policy" content="${policy}"/>`);
}

export function securityHeaders(inputs: HeaderInputs): [string, string][] {
  const { maxAgeSeconds, includeSubDomains } = inputs.hsts;
  return [
    ["Content-Security-Policy", headerCsp(inputs)],
    // Never `preload` from here: joining the browser preload list is hard to undo and is the owner's decision.
    ["Strict-Transport-Security", `max-age=${maxAgeSeconds}${includeSubDomains ? "; includeSubDomains" : ""}`],
    ["X-Content-Type-Options", "nosniff"],
    ["X-Frame-Options", "DENY"],
    ["Referrer-Policy", "strict-origin-when-cross-origin"],
    ["Permissions-Policy", DENIED_FEATURES.map((f) => `${f}=()`).join(", ")],
    ["Cross-Origin-Opener-Policy", "same-origin"],
    ["Cross-Origin-Embedder-Policy", "require-corp"],
    ["Cross-Origin-Resource-Policy", "same-origin"],
  ];
}

/** Cloudflare `_headers` file. Rules that match the same URL are combined. */
export function headersFile(inputs: HeaderInputs): string {
  const p = inputs.basePath;
  const lines: string[] = [`${p}/*`, ...securityHeaders(inputs).map(([k, v]) => `  ${k}: ${v}`)];
  // Static files never need to load anything. A second policy only ever tightens the first.
  for (const path of [`${p}/_next/*`, `${p}/icon.svg`, `${p}/sitemap.xml`]) {
    lines.push(path, "  Content-Security-Policy: default-src 'none'; frame-ancestors 'none'");
  }
  // The social preview image must be loadable from other sites (link previews).
  lines.push(`${p}/opengraph-image.png`, "  ! Cross-Origin-Resource-Policy", "  Cross-Origin-Resource-Policy: cross-origin");
  const tooLong = lines.find((l) => l.length > 2000);
  if (tooLong) throw new Error(`_headers line over Cloudflare's 2,000 character limit: ${tooLong.slice(0, 60)}…`);
  return `${lines.join("\n")}\n`;
}

export function securityTxt(args: { siteUrl: string; contactEmail: string; expires: Date; repoUrl?: string }): string {
  return [
    `Contact: mailto:${args.contactEmail}`,
    ...(args.repoUrl ? [`Contact: ${args.repoUrl}/security/advisories/new`] : []),
    `Expires: ${args.expires.toISOString()}`,
    "Preferred-Languages: en",
    `Canonical: ${args.siteUrl}/.well-known/security.txt`,
    `Policy: ${args.siteUrl}/security/`,
    "",
  ].join("\n");
}

function walk(dir: string): string[] {
  return readdirSync(dir).flatMap((name) => {
    const full = join(dir, name);
    return statSync(full).isDirectory() ? walk(full) : [full];
  });
}

async function main() {
  const root = join(dirname(fileURLToPath(import.meta.url)), "..");
  const out = join(root, "out");
  if (!existsSync(out)) throw new Error("out/ not found. Run `next build` first.");

  // Loaded by URL so Node runs the TypeScript file directly; typed from the module itself.
  const config: typeof import("../site.config") = await import(pathToFileURL(join(root, "site.config.ts")).href);
  const { siteConfig } = config;
  const inputs: HeaderInputs = {
    siteUrl: siteConfig.siteUrl,
    basePath: siteConfig.basePath,
    formEndpoint: formSource(process.env.NEXT_PUBLIC_WAITLIST_ENDPOINT),
    hsts: siteConfig.security.hsts,
  };

  const validDays = siteConfig.security.securityTxtValidDays;
  if (!(validDays > 0 && validDays < 365)) throw new Error("security.securityTxtValidDays must be between 1 and 364.");

  const pages = walk(out).filter((f) => f.endsWith(".html"));
  let maxHashes = 0;
  for (const file of pages) {
    const html = readFileSync(file, "utf8");
    const hashes = inlineScriptHashes(html);
    maxHashes = Math.max(maxHashes, hashes.length);
    try {
      writeFileSync(file, insertMetaCsp(html, metaCsp(inputs, hashes)));
    } catch (error) {
      throw new Error(`${relative(out, file)}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  writeFileSync(join(out, "_headers"), headersFile(inputs));
  mkdirSync(join(out, ".well-known"), { recursive: true });
  writeFileSync(
    join(out, ".well-known", "security.txt"),
    securityTxt({
      siteUrl: siteConfig.siteUrl,
      contactEmail: siteConfig.contactEmail,
      expires: new Date(Date.now() + validDays * 86_400_000),
      repoUrl: siteConfig.repoUrl,
    }),
  );

  // Publish the third-party notices next to the code they cover.
  const notices = join(root, "NOTICES");
  if (!existsSync(notices)) throw new Error("NOTICES not found. Run `npm run licences`.");
  writeFileSync(join(out, "NOTICES.txt"), readFileSync(notices));

  process.stdout.write(
    `postbuild OK: CSP added to ${pages.length} pages (up to ${maxHashes} script hashes each), form ${inputs.formEndpoint ? "pinned to its endpoint" : "not connected"}, _headers, security.txt and NOTICES.txt written\n`,
  );
}

// Run only when executed directly (not when imported by tests). realpath: works from a symlinked checkout too.
const invoked = process.argv[1] ? realpathSync(process.argv[1]) : "";
if (invoked === realpathSync(fileURLToPath(import.meta.url))) {
  main().catch((error: unknown) => {
    process.stderr.write(`postbuild FAILED: ${error instanceof Error ? error.message : String(error)}\n`);
    process.exit(1);
  });
}
